package com.mediexplain.web;
import com.mediexplain.model.*;import com.mediexplain.repo.*;import com.mediexplain.service.*;import jakarta.validation.constraints.*;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@Controller public class WebController {
 private final AccountService accounts;private final ReportRepository reports;private final ConversationRepository conversations;private final MessageRepository messages;private final PdfReportService pdf;private final ConversationService chat;
 public WebController(AccountService a,ReportRepository r,ConversationRepository c,MessageRepository m,PdfReportService p,ConversationService ch){accounts=a;reports=r;conversations=c;messages=m;pdf=p;chat=ch;}
 private AppUser user(Authentication auth){return accounts.current(auth.getName());}
 @GetMapping("/") String home(){return "home";}
 @GetMapping("/register") String register(Model m){m.addAttribute("name","");m.addAttribute("email","");return "register";}
 @PostMapping("/register") String registerPost(@RequestParam String name,@RequestParam String email,@RequestParam String password,Model m){if(name.isBlank()||name.length()>100||!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")||password.length()<8||password.length()>72){m.addAttribute("error","Enter a name and valid email. Password must be 8–72 characters.");m.addAttribute("name",name);m.addAttribute("email",email);return "register";}try{accounts.register(name,email,password);return "redirect:/login?registered";}catch(IllegalArgumentException e){m.addAttribute("error",e.getMessage());m.addAttribute("name",name);m.addAttribute("email",email);return "register";}}
 @GetMapping("/login") String login(){return "login";}
 @GetMapping("/dashboard") String dashboard(Authentication a,Model m){AppUser u=user(a);m.addAttribute("user",u);m.addAttribute("reports",reports.findByOwnerOrderByUploadedAtDesc(u));m.addAttribute("conversations",conversations.findByOwnerOrderByCreatedAtDesc(u).stream().limit(5).toList());return "dashboard";}
 @GetMapping("/reports/upload") String upload(){return "upload";}
 @PostMapping("/reports/upload") String uploadPost(@RequestParam("file") MultipartFile file,Authentication a,Model m){try{return "redirect:/reports/"+pdf.upload(user(a),file).getId();}catch(IllegalArgumentException e){m.addAttribute("error",e.getMessage());return "upload";}}
 @GetMapping("/reports/{id}") String report(@PathVariable Long id,Authentication a,Model m){MedicalReport r=reports.findByIdAndOwner(id,user(a)).orElseThrow(()->new NoSuchElementException());m.addAttribute("report",r);return "report";}
 @PostMapping("/reports/{id}/chat") String start(@PathVariable Long id,Authentication a){return "redirect:/conversations/"+chat.start(user(a),id).getId();}
 @GetMapping("/conversations") String history(Authentication a,Model m){m.addAttribute("conversations",conversations.findByOwnerOrderByCreatedAtDesc(user(a)));return "history";}
 @GetMapping("/conversations/{id}") String conversation(@PathVariable Long id,Authentication a,Model m){Conversation c=conversations.findByIdAndOwner(id,user(a)).orElseThrow(()->new NoSuchElementException());m.addAttribute("conversation",c);m.addAttribute("messages",messages.findByConversationOrderByCreatedAtAsc(c));m.addAttribute("submissionKey",UUID.randomUUID().toString());return "chat";}
 @PostMapping("/conversations/{id}/messages") String message(@PathVariable Long id,@RequestParam String question,@RequestParam String submissionKey,Authentication a,Model m){try{chat.ask(user(a),id,question,submissionKey);return "redirect:/conversations/"+id;}catch(IllegalArgumentException|IllegalStateException e){Conversation c=conversations.findByIdAndOwner(id,user(a)).orElseThrow(()->new NoSuchElementException());m.addAttribute("conversation",c);m.addAttribute("messages",messages.findByConversationOrderByCreatedAtAsc(c));m.addAttribute("question",question);m.addAttribute("submissionKey",UUID.randomUUID().toString());m.addAttribute("error",e.getMessage());return "chat";}}
}
